import { test } from '@playwright/test';
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { jpegWithOrientation, pngToApng, webpToAnimated } from './builders';

const here = (name: string) => fileURLToPath(new URL(name, import.meta.url));

test('generate fixtures', async ({ page }) => {
  /** Left half red, right half blue. */
  const encode = (mime: string, w: number, h: number) =>
    page.evaluate(async ({ mime, w, h }) => {
      const c = document.createElement('canvas');
      c.width = w;
      c.height = h;
      const g = c.getContext('2d')!;
      g.fillStyle = 'rgb(220,30,30)';
      g.fillRect(0, 0, w / 2, h);
      g.fillStyle = 'rgb(30,30,220)';
      g.fillRect(w / 2, 0, w / 2, h);
      const b: Blob = await new Promise((r) => c.toBlob((x) => r(x!), mime, 0.92));
      return [...new Uint8Array(await b.arrayBuffer())];
    }, { mime, w, h });

  const png = new Uint8Array(await encode('image/png', 48, 32));
  const webp = new Uint8Array(await encode('image/webp', 48, 32));
  // Stored 40 × 20 (red left, blue right) with EXIF orientation 6 = rotate
  // 90° clockwise, so it displays as 20 × 40 with red on top.
  const jpg = new Uint8Array(await encode('image/jpeg', 40, 20));

  const b64 = (u8: Uint8Array) => Buffer.from(u8).toString('base64');
  const source = [
    '// Generated by tests/fixtures/generate-fixtures.spec.ts (npm run fixtures). Do not edit.',
    '// Binary fixtures are stored as base64 text so they survive tools that',
    '// rewrite image files (e.g. by adding metadata) and diff cleanly in Git.',
    '',
    '/** Two identical frames, 48 × 32, left half red, right half blue. */',
    `export const animatedPng = '${b64(pngToApng(png, 2))}';`,
    '',
    '/** Animated WebP: two identical frames, 48 × 32, left half red, right half blue. */',
    `export const animatedWebp = '${b64(webpToAnimated(webp, 48, 32, 2))}';`,
    '',
    '/** Stored 40 × 20 (red left, blue right) with EXIF orientation 6: displays as 20 × 40, red on top. */',
    `export const rotatedJpeg = '${b64(jpegWithOrientation(jpg, 6))}';`,
    '',
    "export const fixture = (b64: string): Buffer => Buffer.from(b64, 'base64');",
    '',
  ].join('\n');
  await writeFile(here('images.ts'), source);
});
